<?php
require_once '../includes/auth.php'; require_role('student'); require_once '../config/db.php'; require_once '../includes/academic.php';
$page_title='Assignments'; $msg=''; $err=''; $user=$_SESSION['username'];
$st=$conn->prepare("SELECT batch_id FROM tbl_student WHERE username=? AND approved=1");$st->bind_param('s',$user);$st->execute();$student=$st->get_result()->fetch_assoc();$batchId=(int)($student['batch_id']??0);$academic=academic_context($conn,$user);$currentSemester=(int)($academic['current_semester']??0);

if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['submit_assignment'])){
    $assignmentId=(int)($_POST['assignment_id']??0);$file=$_FILES['assignment']??null;$allowed=['pdf','doc','docx','ppt','pptx','zip'];
    $st=$conn->prepare("SELECT a.*,b.batch_name FROM tbl_assignments a JOIN tbl_batches b ON b.id=a.batch_id WHERE a.id=? AND a.batch_id=? AND a.semester=? AND b.active=1");$st->bind_param('iii',$assignmentId,$batchId,$currentSemester);$st->execute();$assignment=$st->get_result()->fetch_assoc();
    if(!$assignment)$err='This assignment is not assigned to your batch.';elseif(!$file||$file['error']!==UPLOAD_ERR_OK)$err='Choose a valid file.';elseif($assignment['due_date']<date('Y-m-d'))$err='The submission deadline has passed.';else{
        $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));
        if(!in_array($ext,$allowed,true))$err='Supported files: PDF, DOC, DOCX, PPT, PPTX and ZIP.';else{
            $dir=__DIR__.'/../uploads/assignments/';if(!is_dir($dir))mkdir($dir,0777,true);$name=time().'_'.bin2hex(random_bytes(4)).'_'.preg_replace('/[^A-Za-z0-9._-]/','_',basename($file['name']));
            if(!move_uploaded_file($file['tmp_name'],$dir.$name))$err='Unable to upload the file.';else{
                $check=$conn->prepare("SELECT id,assignment_file_path FROM tbl_student_assignments WHERE assignment_id=? AND username=?");$check->bind_param('is',$assignmentId,$user);$check->execute();$existing=$check->get_result()->fetch_assoc();
                if($existing){@unlink($dir.basename($existing['assignment_file_path']));$st=$conn->prepare("UPDATE tbl_student_assignments SET assignment_file_path=?,subject=?,teacher_username=?,assignment_status=0,submitted_at=CURRENT_TIMESTAMP WHERE id=? AND username=? AND assignment_id=?");$st->bind_param('sssisi',$name,$assignment['subject'],$assignment['teacher_username'],$existing['id'],$user,$assignmentId);}
                else{$st=$conn->prepare("INSERT INTO tbl_student_assignments(username,assignment_id,assignment_file_path,subject,teacher_username,assignment_status) VALUES(?,?,?,?,?,0)");$st->bind_param('sisss',$user,$assignmentId,$name,$assignment['subject'],$assignment['teacher_username']);}
                if($st->execute())$msg='Assignment submitted to '.$assignment['teacher_username'].'.';else{$err='Could not save submission.';@unlink($dir.$name);}
            }
        }
    }
}

$st=$conn->prepare("SELECT a.*,t.name teacher_name,b.batch_name FROM tbl_assignments a JOIN tbl_trs t ON t.username=a.teacher_username JOIN tbl_batches b ON b.id=a.batch_id WHERE a.batch_id=? AND a.semester=? AND t.approved=1 AND a.due_date>=CURDATE() ORDER BY a.due_date,a.id DESC");$st->bind_param('ii',$batchId,$currentSemester);$st->execute();$available=$st->get_result();
$st=$conn->prepare("SELECT sa.*,a.title,a.due_date,t.name teacher_name,b.batch_name FROM tbl_student_assignments sa JOIN tbl_assignments a ON a.id=sa.assignment_id JOIN tbl_trs t ON t.username=sa.teacher_username LEFT JOIN tbl_batches b ON b.id=a.batch_id WHERE sa.username=? ORDER BY sa.id DESC");$st->bind_param('s',$user);$st->execute();$history=$st->get_result();
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">STUDENT WORK</span><h2>Assignments</h2><p>Only work assigned to your current semester appears here. Your submission goes automatically to the teacher who created it.</p></div><div class="hero-orb"><i class="fa-solid fa-file-arrow-up"></i></div></div>
<?php if($msg): ?><div class="alert alert-success glass-alert"><?php echo e($msg); ?></div><?php endif; ?><?php if($err): ?><div class="alert alert-danger glass-alert"><?php echo e($err); ?></div><?php endif; ?>
<div class="row g-4"><div class="col-xl-7"><div class="glass-card"><div class="section-kicker">YOUR BATCH</div><h5>Open Assignments</h5><?php if(!$batchId): ?><div class="context-warning"><i class="fa-solid fa-circle-info"></i><div><strong>Batch not assigned</strong><p>Ask the administrator to assign your batch.</p></div></div><?php elseif($available->num_rows===0): ?><div class="empty mt-3">No active assignments for your batch right now.</div><?php endif; ?><?php while($a=$available->fetch_assoc()): ?><div class="assignment-card glass-subcard mt-3"><div class="d-flex justify-content-between gap-3"><div><span class="context-chip small-chip"><?php echo e($a['batch_name']); ?></span><h6 class="mt-2"><?php echo e($a['title']); ?></h6><div class="small-muted"><?php echo e($a['subject']); ?> · Assigned by <?php echo e($a['teacher_name']); ?></div></div><span class="due-pill">Due <?php echo e($a['due_date']); ?></span></div><?php if($a['description']): ?><p class="small-muted mt-3"><?php echo nl2br(e($a['description'])); ?></p><?php endif; ?><form method="POST" enctype="multipart/form-data" class="mt-3"><input type="hidden" name="submit_assignment" value="1"><input type="hidden" name="assignment_id" value="<?php echo (int)$a['id']; ?>"><div class="input-group"><input class="form-control" type="file" name="assignment" accept=".pdf,.doc,.docx,.ppt,.pptx,.zip" required><button class="btn btn-primary">Submit</button></div></form></div><?php endwhile; ?></div></div>
<div class="col-xl-5"><div class="glass-card"><div class="section-kicker">HISTORY</div><h5>My Submissions</h5><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Assignment</th><th>Status</th></tr></thead><tbody><?php if($history->num_rows===0): ?><tr><td colspan="2" class="empty">No submissions yet.</td></tr><?php endif; ?><?php while($h=$history->fetch_assoc()): ?><tr><td><a target="_blank" href="../uploads/assignments/<?php echo rawurlencode(basename($h['assignment_file_path'])); ?>"><?php echo e($h['title']); ?></a><br><span class="small-muted"><?php echo e($h['teacher_name']); ?></span></td><td><?php echo $h['assignment_status']?'<span class="badge text-bg-success">Reviewed</span>':'<span class="badge text-bg-info">Submitted</span>'; ?></td></tr><?php endwhile; ?></tbody></table></div></div></div></div>
<?php require '../includes/footer.php'; ?>
